head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[session > M > getAttribute]<br/>브라우저 세션에서 key 파라미터에 해당하는 값을 반환합니다.",
    "validation" : [
        "key(필수) 파라미터로 조회할 세션 데이터의 키를 설정할 수 있어야 합니다.",
        "key 파라미터에 해당하는 세션 데이터 값을 반환해야 합니다.",
        "key 파라미터에 해당하는 값이 없으면 null 을 반환해야 합니다.",
        "XML Document 타입으로 저장된 값은 XML 파싱되어 반환되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 시나리오 검증용 세션 데이터 사전 등록
    WebSquare.session.setAttribute("userName", "Hong");
    WebSquare.session.setAttribute("xmlData", WebSquare.xml.parse("<book><title>Harry Potter</title><price>29.99</price></book>"));
};



scwin.btn_getAttribute_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : 일반 String 값 조회
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 일반 값 조회 (key='userName') ──");

        var result = WebSquare.session.getAttribute("userName");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + (typeof result) + " / 반환값 : '" + result + "'");
    } else if (scenario === "2") {
        // 시나리오 2 : 존재하지 않는 키 조회 → null
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : 존재하지 않는 키 조회 (key='notExist') ──");

        var result = WebSquare.session.getAttribute("notExist");
        wf_body_bottom.getObj("scwin").setReturnValue("반환값 : " + result);
    } else if (scenario === "3") {
        // 시나리오 3 : XML Document 저장값 조회 → XML 파싱되어 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : XML Document 조회 (key='xmlData') ──");

        var result = WebSquare.session.getAttribute("xmlData");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + (typeof result) + " / nodeType : " + (result ? result.nodeType : "null"));
        if (result) {
            var serialized = WebSquare.xml.serialize(result);
            wf_body_bottom.getObj("scwin").setReturnValue("XML 직렬화 : " + serialized.replace(/\s+/g, " ").replace(/>\s+</g, "><"));
        }
    }
};
